package com.govweb.application;
import com.govweb.service.Service; import com.govweb.user.User; import jakarta.persistence.*; import jakarta.validation.constraints.*; import lombok.*; import java.time.*;
@Entity @Getter @Setter @NoArgsConstructor public class GovApplication { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String referenceNumber; @ManyToOne(optional=false) private Service service; @ManyToOne(optional=false) private User citizen; @NotBlank private String applicantName; private String dateOfBirth; private String citizenshipNumber; private String contactNumber; private String address; @Enumerated(EnumType.STRING) private ApplicationStatus status=ApplicationStatus.SUBMITTED; private String remarks; private LocalDateTime createdAt=LocalDateTime.now(); }
